const cases = ['Super+Return', 'super+return', 'Super+Shift+1', 'Shift+Super+1', 'Ctrl+Alt+Delete', 'control+alt+delete', 'Primary+q', 'Super+Q',
'Super+pagedown', 'Super+Page_Down', 'Super+plus', 'XF86AudioMute', 'Super', 'Logo+Return', 'Mod1+Tab', 'Super+MouseLeft+Drag',
'super+mouseleft+drag', 'Super+MouseLeft', 'Super+MouseLeft+Click', 'MouseMiddle', 'Super+Wheel', 'Super+wheelup', 'Swipe3Left', 'swipe4',
'pinch2in', 'Pinch5Out', 'Swipe2Up'];
rec('canonical', cases.map((c) => [c, parseTrigger(c).text, parseTrigger(c).modifiers.join()]));
rec('claims', ['Super+1', 'Super+Shift+1', 'Ctrl+Alt+Delete', 'Super+MouseLeft+Drag', 'Super+MouseLeft', 'Super', 'Swipe3Left', 'Super+Wheel'].map((t) => [t, JSON.stringify(claimOf(parseTrigger(t)))]));

const bad = ['', 'Super+', 'Super++1', '+Super', 'Super+Shift', 'Shift', 'Super+Super+1', 'Super+a+b', 'a+Super', 'Super+!', 'Super+Mod4+1', 'Super+Drag',
'MouseLeft+MouseRight', 'Super+MouseLeft+a', 'Swipe1Left', 'Swipe6', 'Swipe3In', 'Pinch3Left', 'Super+Swipe3', 'Super + 1', 'Super+Ctrl-1',
'Super+MouseLeft+Drag+Drag', 'Super+Wheel+Wheel', 'Super+Return+Drag'];
rec('refused', bad.map((c) => { try { parseTrigger(c, 'trigger'); return [c, 'accepted']; } catch (e) { return [c, e.name + ': ' + e.message + ' [' + e.token + ']']; } }));

const list = (layout) => [...layout.bindings].map((b) => b.id + '=' + b.trigger).join(',');
const defaults = new FloatingLayout();
const out = [list(new FloatingLayout()), list(new FloatingLayout({ triggers: { resize: null } })), list(new FloatingLayout({ triggers: { move: undefined } })),
list(new FloatingLayout({ triggers: { move: 'Alt+MouseLeft+Drag', resize: null } }))];
defaults.bindings.get('move').trigger = 'Alt+MouseLeft+Drag';
out.push(list(defaults), defaults.bindings.remove('resize'), String(defaults.bindings.get('resize')));
defaults.bindings.clear(); out.push(defaults.bindings.size);
out.push(fail(() => new FloatingLayout({ triggers: { move: 'Super+MouseLeft+Drag', resize: 'Super+MouseLeft+Drag' } })));
rec('floating', out);
